'use client';

import React from 'react';
import NextLink from 'next/link';
import dynamic from 'next/dynamic';
import { Theme } from '@astryxdesign/core/theme';
import { LinkProvider } from '@astryxdesign/core/Link';
import { VStack } from '@astryxdesign/core/Layout';
// Pre-built theme (generated by `astryx theme build`) — its CSS ships in
// neutral.css, so Astryx skips runtime style injection.
import { neutralTheme } from '@/theme/neutral';
import { SyllabiProvider, useSyllabi } from '@/lib/store';
import { Navigation } from '@/components/Navigation';
import { Footer } from '@/components/Footer';
import { CookieBanner } from '@/components/CookieBanner';
import { ToastPresenter } from '@/components/ToastPresenter';
import { NavigationProgress } from '@/components/NavigationProgress';

const GoogleAuthModal = dynamic(
  () => import('@/components/GoogleAuthModal').then((mod) => mod.GoogleAuthModal),
  { ssr: false }
);

function ThemedShell({ children }: { children: React.ReactNode }) {
  const { themeMode, isGoogleModalOpen } = useSyllabi();

  return (
    <Theme theme={neutralTheme} mode={themeMode}>
      <VStack
        gap={0}
        style={{
          minHeight: '100vh',
          backgroundColor: 'var(--color-background-body)',
          color: 'var(--color-text-primary)',
        }}
      >
        <React.Suspense fallback={null}>
          <NavigationProgress />
        </React.Suspense>
        <Navigation />
        <main style={{ flex: 1, width: '100%' }}>{children}</main>
        <Footer />
        <CookieBanner />
        <ToastPresenter />
        {isGoogleModalOpen && <GoogleAuthModal />}
      </VStack>
    </Theme>
  );
}

export function AppProviders({ children }: { children: React.ReactNode }) {
  return (
    // Every Astryx link surface (Button href, ClickableCard, TopNavItem, Link)
    // routes through next/link → client-side navigation + prefetching.
    <LinkProvider component={NextLink}>
      <SyllabiProvider>
        <ThemedShell>{children}</ThemedShell>
      </SyllabiProvider>
    </LinkProvider>
  );
}
